def compute(vars):
    net_profit_margin = vars["Net Profit Margin"]
    total_asset_turnover = vars["Total Asset Turnover"]
    return_on_assets = net_profit_margin * total_asset_turnover
    return {
        "value": return_on_assets,
        "trace": {
            "Net Profit Margin": net_profit_margin,
            "Total Asset Turnover": total_asset_turnover,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "ratio"
            }
        }
    }
